sp_widget.css:
.my-bookings-page {
  padding: 30px;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 25px;
}

.page-header h2 {
  margin: 0;
  font-weight: 700;
}

.table {
  background: #ffffff;
}

.table th,
.table td {
  vertical-align: middle !important;
}

sp_widget.script:
(function() {

    data.bookings = [];

    var bookingGR = new GlideRecord(
        'x_1958892_smart_0_parking_booking'
    );

    bookingGR.addQuery(
        'requested_by',
        gs.getUserID()
    );

    bookingGR.orderByDesc('sys_created_on');
    bookingGR.query();

    while (bookingGR.next()) {

        data.bookings.push({

            sys_id:
                bookingGR.getUniqueValue(),

            booking_number:
                bookingGR.getDisplayValue(
                    'booking_number'
                ),

            parking_location:
                bookingGR.getDisplayValue(
                    'parking_location'
                ),

            parking_slot:
                bookingGR.getDisplayValue(
                    'parking_slot'
                ),

            vehicle:
                bookingGR.getDisplayValue(
                    'vehicle'
                ),

            start_time:
                bookingGR.getDisplayValue(
                    'start_time'
                ),

            end_time:
                bookingGR.getDisplayValue(
                    'end_time'
                ),

            status:
                bookingGR.getDisplayValue(
                    'booking_status'
                )
        });
    }

})();
